1	/**
2	 * C-07 Rules Engine core types (C07-T02).
3	 * Source of truth: docs/components/rules-engine/DESIGN.md §5 and
4	 * docs/interfaces/share-modifier-api.md.
5	 *
6	 * Type-only module: no runtime logic, no I/O.
7	 */
8	
9	// ---------------------------------------------------------------------------
10	// §5.1 Identifiers & enums
11	// ---------------------------------------------------------------------------
12	
13	export type CharacterId = "gnome" | "sprite" | "halfling" | "dwarf";
14	
15	export type Rarity = "common" | "rare" | "unique" | "set";
16	
17	export type LootTableId =
18	  | "world"
19	  | "wooden_chest"
20	  | "silver_chest"
21	  | "gold_chest"
22	  | "magic_chest";
23	
24	export type ModifierKind = "reward" | "penalty";
25	
26	export type Uniqueness = "unique" | "common";
27	
28	export type SeatId = 0 | 1 | 2 | 3;
29	
30	// ---------------------------------------------------------------------------
31	// §5.2 Treasure
32	// ---------------------------------------------------------------------------
33	
34	export interface TreasureDef {
35	  /** Stable slug, e.g. "stone_icon". */
36	  id: string;
37	  /** Display name, e.g. "Stone Icon". */
38	  name: string;
39	  rarity: Rarity;
40	  /** Integer GP. */
41	  baseValueGp: number;
42	  /** If piece of a set. */
43	  setId?: string;
44	  /** Optional order within set. */
45	  setPieceIndex?: number;
46	  /** False for coin sacks (no stack height). */
47	  stackableVisual: boolean;
48	  /** True for Unique rarity (and set pieces as non-duplicate). */
49	  unique: boolean;
50	  /** Wooden/silver/gold/magic chest shells. */
51	  isChest: boolean;
52	  /** Which table this chest opens into. */
53	  chestTable?: LootTableId;
54	  flags?: {
55	    /** Jammy item (DESIGN §7.1 jammy). */
56	    goatOnPole?: boolean;
57	  };
58	}
59	
60	export interface TreasureInstance {
61	  instanceId: string;
62	  defId: string;
63	  /** After chest open, revealed value. Position/owner are sim concerns. */
64	  valueOverrideGp?: number;
65	}
66	
67	export interface SetDef {
68	  id: string;
69	  name: string;
70	  /** Length 2..5 per design. */
71	  pieceDefIds: string[];
72	  /** Design "Value" column (per piece). */
73	  pieceBaseValueGp: number;
74	  /** e.g. 10, 200, 2000. */
75	  setBonusPercent: number;
76	}
77	
78	// ---------------------------------------------------------------------------
79	// §6.7 Inventory valuation results
80	// ---------------------------------------------------------------------------
81	
82	export interface SetCompletion {
83	  setId: string;
84	  name: string;
85	  /** setGrossGp - sum(piece bases), or full setGross for display. */
86	  bonusGp: number;
87	  setGrossGp: number;
88	  contributors: { seatId: SeatId; pieces: number; awardedGp: number }[];
89	}
90	
91	export interface InventoryValueResult {
92	  /** Party total after set supersession. */
93	  totalGp: number;
94	  perSeatGp: { seatId: SeatId; gp: number }[];
95	  setCompletions: SetCompletion[];
96	}
97	
98	/** Context passed to treasure rolls (excluded live uniques, set hints…). */
99	export interface RollContext {
100	  /** Unique/set defs already live in the world or held — never re-rolled. */
101	  excludedDefIds?: string[];
102	  /** For magic chests: piece ids that would complete an almost-done set. */
103	  preferredSetPieceDefIds?: string[];
104	}
105	
106	// ---------------------------------------------------------------------------
107	// §5.3 Encumbrance
108	// ---------------------------------------------------------------------------
109	
110	export interface EncumbranceConfig {
111	  /** Design: 3. */
112	  freeItems: number;
113	  /** Playtest-tunable; default placeholder 0.12. */
114	  speedPenaltyPerExtra: number;
115	  /** Default placeholder 0.12. */
116	  jumpPenaltyPerExtra: number;
117	  /** 0 allows Greed Overwhelming. */
118	  minSpeedMultiplier: number;
119	  minJumpMultiplier: number;
120	  /** Optional weight-based term (0 = count-only MVP). */
121	  weightSpeedFactor?: number;
122	}
123	
124	export interface EncumbranceResult {
125	  freeItems: number;
126	  /** max(0, carryCount - freeItems). */
127	  extraItems: number;
128	  /** Clamped [min, 1]. */
129	  speedMultiplier: number;
130	  jumpMultiplier: number;
131	  /** speedMultiplier === 0. */
132	  isSpeedZero: boolean;
133	}
134	
135	// ---------------------------------------------------------------------------
136	// §5.4 Stats & score context
137	// ---------------------------------------------------------------------------
138	
139	export interface PlayerStats {
140	  // Exit order (session aggregate)
141	  /** Levels exited first. */
142	  exitsFirstCount: number;
143	  exitsLastCount: number;
144	  /** True iff first on EVERY completed level (Leader of the Pack). */
145	  alwaysFirstExit: boolean;
146	  /** True iff last on EVERY completed stage (Slowpoke). */
147	  alwaysLastExit: boolean;
148	
149	  // Treasure economy
150	  /** Optional pre-agg; rules prefers inventory recompute. */
151	  treasureRecoveredValueGp: number;
152	  treasureLostCount: number;
153	  /** Final recovered item count (or session haul count). */
154	  itemsHauledCount: number;
155	  /** Pieces this seat holds in sets that party completed. */
156	  setPiecesInCompletedSets: number;
157	  /** Remedial Archaeology. */
158	  lostSetItemDuringEscape: boolean;
159	
160	  // Motion
161	  airTimeTicks: number;
162	  groundTimeTicks: number;
163	
164	  // Combat / traps
165	  trapsHit: number;
166	  /** Trip/push hits on other players. */
167	  hitsDealt: number;
168	  hitsTaken: number;
169	  /** Distinct seats this player hit (Disciplinarian). */
170	  playersHitSeatIds: SeatId[];
171	  stunnedOrHurtCount: number;
172	
173	  // Control / AI
174	  humanControlTicks: number;
175	  aiControlTicks: number;
176	  /** Human↔AI transitions. */
177	  controlSwaps: number;
178	  /** Antisocial: sole human entire session. */
179	  onlyHumanForWholeGame: boolean;
180	
181	  // Inventory shape at end
182	  /** Items when leaving Level 0 Hoard. */
183	  hoardExitItemCount: number;
184	  /** Items at dungeon exit. */
185	  finalItemCount: number;
186	  /** Gambler (final haul is only chest-origin items). */
187	  onlyChestsRecovered: boolean;
188	  /** Undiscerning. */
189	  onlyCommonRecovered: boolean;
190	  /** Greed Overwhelming ever true. */
191	  speedZeroFromWeight: boolean;
192	  /** Jammy. */
193	  goatOnPole: boolean;
194	  /** Success! — completed exit (not stuck/quit mid-run). */
195	  successfullyExited: boolean;
196	}
197	
198	export interface ScoreSeat {
199	  seatId: SeatId;
200	  character: CharacterId;
201	  /** Final control affinity for high-score eligibility. */
202	  human: boolean;
203	  stats: PlayerStats;
204	  finalInventory: TreasureInstance[];
205	  /** Mirrors stats.hoardExitItemCount for convenience. */
206	  hoardExitInventoryCount: number;
207	}
208	
209	export interface RankingBuckets {
210	  mostTreasureValue: SeatId[];
211	  mostTrapsHit: SeatId[];
212	  mostHitsDealt: SeatId[];
213	  mostHitsTaken: SeatId[];
214	  mostTreasureLost: SeatId[];
215	  mostAirTime: SeatId[];
216	  leastAirTime: SeatId[];
217	  alwaysFirstExit: SeatId[];
218	  alwaysLastExit: SeatId[];
219	}
220	
221	export interface ScoreContext {
222	  /** Length 4. */
223	  seats: ScoreSeat[];
224	  /** 0..7 design path. */
225	  levelsCompleted: number;
226	  /** Precomputed or filled by buildRankings. */
227	  ranking: RankingBuckets;
228	  /** For Antisocial. */
229	  sessionHadExactlyOneHuman: boolean;
230	}
231	
232	// ---------------------------------------------------------------------------
233	// §5.5 Modifier results & payout
234	// ---------------------------------------------------------------------------
235	
236	export interface ShareModifierDef {
237	  id: string;
238	  title: string;
239	  kind: ModifierKind;
240	  uniqueness: Uniqueness;
241	  /** Fixed delta, or variable (per item / per completed-set piece). */
242	  deltaMode: "fixed" | "per_item" | "per_set_piece";
243	  /** Base; for per_* multiplied by count. */
244	  deltaShares: number;
245	}
246	
247	export interface AppliedModifier {
248	  id: string;
249	  title: string;
250	  kind: ModifierKind;
251	  uniqueness: Uniqueness;
252	  /** Signed int; already scaled for haul/collector. */
253	  deltaShares: number;
254	}
255	
256	export interface PlayerModifierResult {
257	  seatId: SeatId;
258	  modifiers: AppliedModifier[];
259	  /** Sum of deltaShares (may be ≤ 0). */
260	  rawShares: number;
261	  /** max(1, rawShares). */
262	  shares: number;
263	}
264	
265	export interface TakeBreakdown {
266	  totalTreasureGp: number;
267	  totalShares: number;
268	  players: {
269	    seatId: SeatId;
270	    shares: number;
271	    /** (shares / totalShares) * 100 — display float ok. */
272	    sharePercent: number;
273	    /** Integer GP after remainder policy. */
274	    takeGp: number;
275	  }[];
276	}
277	
278	// ---------------------------------------------------------------------------
279	// §5.5 / §10 ScoreReport (rules-side; protocol mirrors a superset for wire)
280	// ---------------------------------------------------------------------------
281	
282	export interface ScoreReportPlayer {
283	  seatId: SeatId;
284	  character: CharacterId;
285	  human: boolean;
286	  /** Display-sorted (DESIGN §9). */
287	  modifiers: AppliedModifier[];
288	  shares: number;
289	  sharePercent: number;
290	  takeGp: number;
291	  inventoryValueGp: number;
292	  /** human && successfullyExited. */
293	  eligibleForHighScore: boolean;
294	}
295	
296	export interface ScoreReport {
297	  rulesetVersion: string;
298	  sessionId: string;
299	  totalTreasureGp: number;
300	  players: ScoreReportPlayer[];
301	  setCompletions: SetCompletion[];
302	  /** 3rd, 2nd, 4th, 1st by takeGp. */
303	  percentageRevealOrder: SeatId[];
304	  /** Slowest→fastest exit (for End Director count phase). */
305	  tossOrder: SeatId[];
306	  completionToken: string;
307	}
308	
309	/** Input to buildScoreReport (DESIGN §4). */
310	export interface ScoreReportInput {
311	  sessionId: string;
312	  /** 4 seats. */
313	  seats: ScoreSeat[];
314	  levelsCompleted: number;
315	  /** Opaque, minted by lobby/sim — rules does not validate crypto. */
316	  completionToken: string;
317	  /** Optional catalog override (tests). */
318	  setCatalog?: SetDef[];
