describe("computeInventoryValue — non-set (C07-T06)", () => {
  it("RULE-06: empty inventories → zero everywhere", () => {
    const result = computeInventoryValue([
      { seatId: 0, items: [] },
      { seatId: 1, items: [] },
      { seatId: 2, items: [] },
      { seatId: 3, items: [] },
    ]);
    expect(result.totalGp).toBe(0);
    expect(result.perSeatGp).toEqual([
